// GEGLU: out[r, j] = gelu_tanh(x[r, j]) * x[r, INNER + j], fp32, rows of 2*INNER.
// One fused one-shot launch. Each thread handles 8 consecutive outputs: two 256-bit loads
// (gate half, linear half) and one 256-bit store with an L2 evict_last policy.
// gelu_tanh(a) = a * sigmoid(2u) = a / (1 + 2^t), t = -2*sqrt(2/pi)*log2(e) * (a + 0.044715 a^3).
// One MUFU per element (ex2); the reciprocal is an integer-seed estimate refined by one cubic
// (Halley) and one Newton FMA step (rel. error < 1e-6), so no MUFU.RCP.
// Load policy by size: up to EF_MAX_ROWS rows the input loads carry L2::evict_first.
#include <cuda_runtime.h>
#include <stdint.h>

#define INNER 5120
#define THREADS 128
#define CTAS_PER_ROW (INNER / (THREADS * 8))  // 5
#define EF_MAX_ROWS 3072

#define V8 "{%0,%1,%2,%3,%4,%5,%6,%7}"
#define O8 "=f"(v[0]), "=f"(v[1]), "=f"(v[2]), "=f"(v[3]), "=f"(v[4]), "=f"(v[5]), "=f"(v[6]), "=f"(v[7])

template <bool EF>
